;\n 1161 |   enabled: boolean;\n 1162 |   createdAt: string;\n 1163 | }\n 1164 | \n 1165 | function AppRoot() {\n 1166 |   \/\/ Clean up legacy business data from localStorage on startup\n 1167 | \n 1168 |   const {\n 1169 |     currentDoctor,\n 1170 |     currentPatient,\n 1171 |     patientSignOut,\n 1172 |     signOut,\n 1173 |     isInitializing,\n 1174 |   } = useEmailAuth();\n 1175 |   const {\n 1176 |     adminLogin,\n 1177 |     isAdmin: isAdminState,\n 1178 |     adminLogout: adminLogoutFn,\n 1179 |   } = useAdminAuth();\n 1180 | \n 1181 |   \/\/ Auto-logout on inactivity \u2014 active only when someone is logged in\n 1182 |   const isLoggedIn = !!(currentDoctor || currentPatient);\n 1183 |   const handleInactivityLogout = useCallback(() => {\n 1184 |     if (currentDoctor) {\n 1185 |       appendAuditLog({\n 1186 |         timestamp: new Date().toISOString(),\n 1187 |         userRole: currentDoctor.role,\n 1188 |         userName: currentDoctor.name,\n 1189 |         action: \"Auto-logged out due to inactivity\",\n 1190 |         target: \"System\",\n 1191 |       });\n 1192 |       signOut();\n 1193 |     } else if (currentPatient) {\n 1194 |       appendAuditLog({\n 1195 |         timestamp: new Date().toISOString(),\n 1196 |         userRole: \"patient\",\n 1197 |         userName: currentPatient.name,\n 1198 |         action: \"Auto-logged out due to inactivity\",\n 1199 |         target: \"Patient Portal\",\n 1200 |       });\n 1201 |       patientSignOut();\n 1202 |     }\n 1203 |     import(\"sonner\").then(({ toast }) =>\n 1204 |       toast.warning(\"You have been logged out due to inactivity.\"),\n 1205 |     );\n 1206 |   }, [currentDoctor, currentPatient, signOut, patientSignOut]);\n 1207 | \n 1208 |   const { showWarning, secondsRemaining, resetTimer } = useInactivityTimer(\n 1209 |     isLoggedIn ? handleInactivityLogout : () => {},\n 1210 |   );\n 1211 |   const [showAuthModal, setShowAuthModal] = useState(false);\n 1212 |   const [showAdminModal, setShowAdminModal] = useState(false);\n 1213 |   const [showPendingPanel, setShowPendingPanel] = useState(false);\n 1214 |   const [adminUser, setAdminUser] = useState(\"\");\n 1215 |   const [adminPass, setAdminPass] = useState(\"\");\n 1216 |   const [adminError, setAdminError] = useState(\"\");\n 1217 |   const [pendingCount, setPendingCount] = useState(0);\n 1218 |   const [authTab, setAuthTab] = useState(\"staff\");\n 1219 | \n 1220 |   \/\/ \u2500\u2500 Data refresh setup \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n 1221 |   const queryClient = useQueryClient();\n 1222 | \n 1223 |   \/\/ invalidateAll: called after every successful data refresh\n 1224 |   \/\/ so React Query re-fetches from the updated localStorage cache.\n 1225 |   const invalidateAll = useCallback(() => {\n 1226 |     queryClient.invalidateQueries({ queryKey: [\"patients\"] });\n 1227 |     queryClient.invalidateQueries({ queryKey: [\"patient\"] });\n 1228 |     queryClient.invalidateQueries({ queryKey: [\"visits\"] });\n 1229 |     queryClient.invalidateQueries({ queryKey: [\"prescriptions\"] });\n 1230 |     queryClient.invalidateQueries({ queryKey: [\"observations\"] });\n 1231 |     queryClient.invalidateQueries({ queryKey: [\"orders\"] });\n 1232 |     queryClient.invalidateQueries({ queryKey: [\"clinicalNotes\"] });\n 1233 |     queryClient.invalidateQueries({ queryKey: [\"alerts\"] });\n 1234 |     queryClient.invalidateQueries({ queryKey: [\"beds\"] });\n 1235 |     queryClient.invalidateQueries({ queryKey: [\"prescriptionRecords\"] });\n 1236 |     queryClient.invalidateQueries({ queryKey: [\"admissionHistory\"] });\n 1237 |   }, [queryClient]);\n 1238 | \n 1239 | \n 1240 |   \/\/ \u250