      const arr = JSON.parse(storage.getItem(k) || \"[]\") as Array<{\n 1270 |             id: unknown;\n 1271 |             fullName?: string;\n 1272 |             isAdmitted?: boolean;\n 1273 |             patientType?: string;\n 1274 |             status?: string;\n 1275 |           }>;\n 1276 |           for (const p of arr) {\n 1277 |             if (\n 1278 |               p.isAdmitted ||\n 1279 |               p.patientType === \"admitted\" ||\n 1280 |               p.status === \"Admitted\"\n 1281 |             ) {\n 1282 |               const rawId = p.id;\n 1283 |               const pid =\n 1284 |                 typeof rawId === \"string\" && rawId.startsWith(\"__bigint__\")\n 1285 |                   ? rawId.slice(10)\n 1286 |                   : String(rawId);\n 1287 |               admittedIds.add(pid);\n 1288 |               patientNames[pid] = p.fullName || pid;\n 1289 |             }\n 1290 |           }\n 1291 |         } catch {}\n 1292 |       }\n 1293 | \n 1294 |       \/\/ Check reminders for admitted patients\n 1295 |       const checkReminders = (\n 1296 |         reminders: Array<{\n 1297 |           id: string;\n 1298 |           patientId: string;\n 1299 |           drugName: string;\n 1300 |           times?: string[];\n 1301 |           reminderTimes?: string[];\n 1302 |           enabled?: boolean;\n 1303 |           status?: string;\n 1304 |           dose?: string;\n 1305 |         }>,\n 1306 |       ) => {\n 1307 |         for (const r of reminders) {\n 1308 |           const isEnabled =\n 1309 |             r.enabled !== false &&\n 1310 |             r.status !== \"paused\" &&\n 1311 |             r.status !== \"completed\";\n 1312 |           if (!isEnabled || !admittedIds.has(r.patientId)) continue;\n 1313 |           const times = r.times?.length ? r.times : (r.reminderTimes ?? []);\n 1314 |           for (const t of times) {\n 1315 |             if (t !== hhmm) continue;\n 1316 |             const fireKey = `staff-${r.patientId